/* cppi::89f8c354f7344f1a3f157840551335e70bf902fd32ba94e401d498df42e5c2e9 */
SELECT COUNT(*) FROM (SELECT hlt.business_date, hlt.id_model_portfolio, hlt.external_reporting_assetmix, hlt.total_market_value_pc, isf.InvestmentStructureLevel2, isf.InvestmentStructureLevel3, isf.InvestmentStructureLevel4, mpts.model_portfolio_time_series_code_value, mpts.model_portfolio_time_series_name_value, mpts.model_portfolio_time_series_from_date, mpts.model_portfolio_time_series_to_date, CASE WHEN external_reporting_assetmix = 'Nominal Fixed Income' THEN 'Fixed Income' WHEN external_reporting_assetmix = 'Credit' THEN 'Credit Investments' WHEN external_reporting_assetmix = 'Cash' THEN 'Excluded' WHEN InvestmentStructureLevel2 IN ('Active Equities', 'Capital Markets & Factor Investing') THEN 'Excluded' ELSE external_reporting_assetmix END AS derived_mptsfc10_name FROM (SELECT business_date, id_model_portfolio, external_reporting_assetmix, round(sum(total_market_value_pc), 2) AS total_market_value_pc FROM holdings.ma_holding_lookthrough WHERE business_date = DATE '2025-05-31' AND id_model_portfolio IN (SELECT DISTINCT model_portfolio FROM performance.scd_performance_invstr_flatten WHERE InvestmentStructure = 'CPPIB_F24') GROUP BY business_date, id_model_portfolio, external_reporting_assetmix) hlt LEFT JOIN performance.scd_performance_invstr_flatten isf ON hlt.id_model_portfolio = isf.model_portfolio AND isf.business_date = (SELECT max(business_date) FROM performance.scd_performance_invstr_flatten) AND isf.InvestmentStructure = 'CPPIB_F24' LEFT JOIN reference.scd_model_portfolio_timeseries mpts ON isf.model_portfolio = mpts.model_portfolio_id AND mpts.business_date = (SELECT max(business_date) FROM reference.scd_model_portfolio_timeseries) AND model_portfolio_time_series_name = 'model_portfolio_time_series_code_10' AND model_portfolio_time_series_to_date = '4712-12-31'
) dbvrcnt

/* cppi::89f8c354f7344f1a3f157840551335e70bf902fd32ba94e401d498df42e5c2e9 */
SELECT COUNT(*) FROM (SELECT hlt.business_date, hlt.id_model_portfolio, hlt.external_reporting_assetmix, hlt.total_market_value_pc, isf.InvestmentStructureLevel2, isf.InvestmentStructureLevel3, isf.InvestmentStructureLevel4, mpts.model_portfolio_time_series_code_value, mpts.model_portfolio_time_series_name_value, mpts.model_portfolio_time_series_from_date, mpts.model_portfolio_time_series_to_date, CASE WHEN external_reporting_assetmix = 'Nominal Fixed Income' THEN 'Fixed Income' WHEN external_reporting_assetmix = 'Credit' THEN 'Credit Investments' WHEN external_reporting_assetmix = 'Cash' THEN 'Excluded' WHEN InvestmentStructureLevel2 IN ('Active Equities', 'Capital Markets & Factor Investing') THEN 'Excluded' ELSE external_reporting_assetmix END AS derived_mptsfc10_name FROM (SELECT business_date, id_model_portfolio, external_reporting_assetmix, round(sum(total_market_value_pc), 2) AS total_market_value_pc FROM holdings.ma_holding_lookthrough WHERE business_date = DATE '2025-05-31' AND id_model_portfolio IN (SELECT DISTINCT model_portfolio FROM performance.scd_performance_invstr_flatten WHERE InvestmentStructure = 'CPPIB_F24') GROUP BY business_date, id_model_portfolio, external_reporting_assetmix) hlt LEFT JOIN performance.scd_performance_invstr_flatten isf ON hlt.id_model_portfolio = isf.model_portfolio AND isf.business_date = (SELECT max(business_date) FROM performance.scd_performance_invstr_flatten) AND isf.InvestmentStructure = 'CPPIB_F24' LEFT JOIN reference.scd_model_portfolio_timeseries mpts ON isf.model_portfolio = mpts.model_portfolio_id AND mpts.business_date = (SELECT max(business_date) FROM reference.scd_model_portfolio_timeseries) AND model_portfolio_time_series_name = 'model_portfolio_time_series_code_10' AND model_portfolio_time_series_to_date = '4712-12-31'
) dbvrcnt

/* cppi::89f8c354f7344f1a3f157840551335e70bf902fd32ba94e401d498df42e5c2e9 */
SELECT COUNT(*) FROM (SELECT hlt.business_date, hlt.id_model_portfolio, hlt.external_reporting_assetmix, hlt.total_market_value_pc, isf.InvestmentStructureLevel2, isf.InvestmentStructureLevel3, isf.InvestmentStructureLevel4, mpts.model_portfolio_time_series_code_value, mpts.model_portfolio_time_series_name_value, mpts.model_portfolio_time_series_from_date, mpts.model_portfolio_time_series_to_date, CASE WHEN external_reporting_assetmix = 'Nominal Fixed Income' THEN 'Fixed Income' WHEN external_reporting_assetmix = 'Credit' THEN 'Credit Investments' WHEN external_reporting_assetmix = 'Cash' THEN 'Excluded' WHEN InvestmentStructureLevel2 IN ('Active Equities', 'Capital Markets & Factor Investing') THEN 'Excluded' ELSE external_reporting_assetmix END AS derived_mptsfc10_name FROM (SELECT business_date, id_model_portfolio, external_reporting_assetmix, round(sum(total_market_value_pc), 2) AS total_market_value_pc FROM holdings.ma_holding_lookthrough WHERE business_date = DATE '2025-05-31' AND id_model_portfolio IN (SELECT DISTINCT model_portfolio FROM performance.scd_performance_invstr_flatten WHERE InvestmentStructure = 'CPPIB_F24') GROUP BY business_date, id_model_portfolio, external_reporting_assetmix) hlt LEFT JOIN performance.scd_performance_invstr_flatten isf ON hlt.id_model_portfolio = isf.model_portfolio AND isf.business_date = (SELECT max(business_date) FROM performance.scd_performance_invstr_flatten) AND isf.InvestmentStructure = 'CPPIB_F24' LEFT JOIN reference.scd_model_portfolio_timeseries mpts ON isf.model_portfolio = mpts.model_portfolio_id AND mpts.business_date = (SELECT max(business_date) FROM reference.scd_model_portfolio_timeseries) AND model_portfolio_time_series_name = 'model_portfolio_time_series_code_10' AND model_portfolio_time_series_to_date = '4712-12-31'
